import{_ as s,l as i,o as e,c as n,v as t,p as l,x as r,d as h,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"RSA 攻击面","description":"","frontmatter":{"title":"RSA 攻击面","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rsa-attacks.md","filePath":"cs/rsa-attacks.md","lastUpdated":1789023840000}'),A={name:"cs/rsa-attacks.md"};function p(E,a,_,m,u,S){const o=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="rsa-攻击面" tabindex="-1">RSA 攻击面 <a class="header-anchor" href="#rsa-攻击面" aria-label="Permalink to &quot;RSA 攻击面&quot;">​</a></h1><div class="epigraph"><p>RSA 的数学对象很稳，工程对象很脆：填充实现、密钥复用、小指数广播、侧信道比「分解模数」更常把系统打穿。</p><footer>—— Boneh, Twenty Years of Attacks on the RSA Cryptosystem, Notices of the AMS, 1999；对照 Anderson 对实现失败</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/rsa-oaep">OAEP</a>给出正确填充。缺口是<strong>错误清单</strong>：哪些合同一破，归约作废。本课只列机制与防御，不提供利用步骤或参数求解程序。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>OAEP 在实现里若回退到 PKCS#1 v1.5 加密，历史 Bleichenbacher 预言机就会回来——只陈述「可区分的填充错误」。共模多指数、低加密指数广播、公共私钥因子，都是密钥管理与参数选择失败。缺口是把这些收成「不要做」，而不是重讲分解算法。</p><h3 id="侧信道也算攻击面" tabindex="-1">侧信道也算攻击面 <a class="header-anchor" href="#侧信道也算攻击面" aria-label="Permalink to &quot;侧信道也算攻击面&quot;">​</a></h3><p>模幂若按比特走不同时间或不同缓存，密钥位可漏。<a href="/cs/side-channel">侧信道</a>已给模型，本课只把 RSA 实现标进同一模型。</p><p><span class="marginnote">Boneh 1999 综述是合法文献。课程禁止复现其中的构造步骤。防御：OAEP/PSS、恒定时间、一密钥一用途、足够大的随机填充、换 ECDH。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按来源分类：填充预言、代数关系（共模/广播）、弱素数生成、实现泄漏。每类对应一条工程规则。指向后课 ECDH：许多新协议直接离开 RSA 封装。</p>',12)),(e(),l(c,null,{default:r(()=>[d(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20RSA%5B%22RSA%20%E9%99%B7%E9%97%A8%22%5D%20--%3E%20PAD%5B%22%E5%A1%AB%E5%85%85%E5%AE%9E%E7%8E%B0%22%5D%0A%20%20RSA%20--%3E%20KEY%5B%22%E5%AF%86%E9%92%A5%E7%94%9F%E5%91%BD%E5%91%A8%E6%9C%9F%22%5D%0A%20%20RSA%20--%3E%20IMP%5B%22%E6%81%92%E5%AE%9A%E6%97%B6%E9%97%B4%E6%A8%A1%E5%B9%82%22%5D%0A%20%20PAD%20--%3E%20FAIL%5B%22%E5%8F%AF%E5%8C%BA%E5%88%86%E9%94%99%E8%AF%AF%E5%88%99%E5%90%88%E5%90%8C%E7%A0%B4%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>可证明安全只在游戏前提成立时成立。攻击面课的工作是列出前提：唯一用途、不可区分失败、随机填充、大模数、无泄漏实现。分解本身仍难，不等于产品安全。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写因数分解或 Coppersmith 方法的操作指导。下一课椭圆曲线 DH：换群，不换「封装会话键」这一层目标。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>OAEP 是正确形状；实现与密钥管理才是常见破口。</li><li>可区分填充错误、共模、弱随机，都让归约退出。</li><li>一密钥一用途；恒定时间。</li><li>后课 ECDH/X25519 换群做协商。</li><li>出处：Boneh, 1999；Bleichenbacher（作为历史失败模式点名）；Anderson, <em>Security Engineering</em>。</li></ul>',8))])}const B=s(A,[["render",p]]);export{P as __pageData,B as default};
